import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.BxrwG5q5.js";const f=JSON.parse('{"title":"Features Overview","description":"","frontmatter":{},"headers":[],"relativePath":"features/overview.md","filePath":"features/overview.md"}'),i={name:"features/overview.md"};function n(d,e,l,s,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="features-overview" tabindex="-1">Features Overview <a class="header-anchor" href="#features-overview" aria-label="Permalink to &quot;Features Overview&quot;">​</a></h1><blockquote><p>See also: <a href="/config/guide/getting-started.html">Getting Started</a> · <a href="/config/api/">SDK Reference</a> · <a href="/config/guide/concepts.html">Concepts &amp; Glossary</a></p></blockquote><p>A single map of everything <code>@jewel998/config</code> does — the SDK, the delivery API, and the portal. Each row links to the page with the full detail.</p><h2 id="feature-flags-remote-config" tabindex="-1">Feature Flags &amp; Remote Config <a class="header-anchor" href="#feature-flags-remote-config" aria-label="Permalink to &quot;Feature Flags &amp; Remote Config&quot;">​</a></h2><p>Store typed values (boolean, number, string, JSON, array) under dot-notation keys like <code>feature.dark_mode</code> or <code>app.upload_limit</code>, and change them without shipping code. The SDK reads them with typed <code>get&lt;T&gt;()</code> calls and sensible defaults.</p><ul><li><a href="/config/guide/getting-started.html">Getting Started</a> — install, initialize, read flags</li><li><a href="/config/guide/scopes.html">Configuration Scopes</a> — how values resolve</li></ul><h2 id="targeting-delivery" tabindex="-1">Targeting &amp; Delivery <a class="header-anchor" href="#targeting-delivery" aria-label="Permalink to &quot;Targeting &amp; Delivery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td>Segments</td><td>Reusable audience cohorts defined by attribute conditions (DNF logic).</td><td><a href="/config/features/segments.html">Segments</a></td></tr><tr><td>Targeting Rules</td><td>Serve different values per user/segment, in priority order.</td><td><a href="/config/features/targeting.html">Targeting Rules</a></td></tr><tr><td>Percentage Rollouts</td><td>Deterministic, sticky percentage bucketing for canary releases.</td><td><a href="/config/features/rollouts.html">Percentage Rollouts</a></td></tr><tr><td>Scheduling</td><td>Time-based activation of a value.</td><td><a href="/config/features/scheduling.html">Scheduling</a></td></tr><tr><td>Prerequisites</td><td>Gate a flag on other flags&#39; values.</td><td><a href="/config/features/prerequisites.html">Prerequisites</a></td></tr></tbody></table><p>The evaluation pipeline runs in a fixed order: archived → prerequisites → overrides → schedule → targeting → rollout → default.</p><h2 id="sdk" tabindex="-1">SDK <a class="header-anchor" href="#sdk" aria-label="Permalink to &quot;SDK&quot;">​</a></h2><p>Browser-first, zero-dependency SDK. <code>initConfig()</code> is the recommended entry point with a three-tier fetch model (prefetch / page / idle), async <code>get()</code>, version polling, and a global error handler. <code>createConfig()</code> is the advanced entry point with loading strategies, plugins, and consent-aware mode.</p><ul><li><a href="/config/api/">SDK Reference</a> — full API</li><li><a href="/config/guide/loading-strategies.html">Loading Strategies</a> · <a href="/config/guide/storage.html">Storage &amp; Caching</a> · <a href="/config/guide/fetch-flow.html">Fetch Flow</a></li></ul><p><strong>Evaluation modes</strong> are chosen by API key prefix: <code>cid_</code> keys evaluate <strong>server-side</strong> (only resolved values reach the browser, ~200 bytes); <code>svr_</code> keys return full flag data for <strong>local</strong> evaluation via plugins.</p><h2 id="platform-administration" tabindex="-1">Platform &amp; Administration <a class="header-anchor" href="#platform-administration" aria-label="Permalink to &quot;Platform &amp; Administration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td>Environments</td><td>Per-project targets (production/staging) with allowed-domain origin locks.</td><td><a href="/config/features/environments.html">Environments</a></td></tr><tr><td>Team &amp; RBAC</td><td>Members with viewer/editor/admin roles; production is admin-protected.</td><td><a href="/config/features/team.html">Team &amp; RBAC</a></td></tr><tr><td>Audit Log</td><td>Append-only history of every change.</td><td><a href="/config/features/audit-log.html">Audit Log</a></td></tr><tr><td>Webhooks</td><td>Change notifications to Slack, Discord, Teams, Google Chat, or custom endpoints.</td><td><a href="/config/features/webhooks.html">Webhooks</a></td></tr><tr><td>Import / Export</td><td>Bulk CSV/JSON import and export of configs.</td><td><a href="/config/features/import.html">Import</a> · <a href="/config/features/export.html">Export</a></td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li><strong>API keys:</strong> <code>cid_</code> (frontend, server-evaluated) and <code>svr_</code> (backend, full data). Revocable instantly.</li><li><strong>Allowed domains:</strong> restrict which origins may call the API per environment. Requests from other origins get a 403.</li><li><strong>Rate limiting:</strong> per-key request caps.</li><li><strong>Server-side evaluation:</strong> with <code>cid_</code> keys, targeting rules, segments, and rollout percentages never reach the browser.</li><li><strong>RBAC:</strong> role-based access enforced by Firestore security rules.</li></ul><p>See <a href="/config/compliance/gdpr.html">GDPR</a> and <a href="/config/compliance/soc2.html">SOC 2</a> for compliance detail.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Designed to run at <code>$0/month</code> on Firebase&#39;s free tier for small-to-medium scale, with CDN-absorbed version polling and version-gated refresh keeping function invocations low. See <a href="/config/guide/cost.html">Cost &amp; Scaling</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/guide/getting-started.html">Getting Started</a> — up and running in 5 minutes</li><li><a href="/config/guide/self-hosting.html">Self-Hosting</a> — deploy to your own Firebase</li><li><a href="/config/api/">SDK Reference</a> — complete API documentation</li><li><a href="/config/contributing/architecture.html">Architecture</a> — how it all fits together</li></ul>',22)])])}const u=t(i,[["render",n]]);export{f as __pageData,u as default};
